# Download the ATC/DDD index pages as raw HTML for the silver layer.
# The site asks clients to wait between requests; keep the 10-second delay.
# This script was generated by AI

library(rvest)

endpoint <- "https://atcddd.fhi.no/atc_ddd_index"
bronze_dir <- "./src/1 bronze/staging area/atc_ddd"
dir.create(bronze_dir, recursive = TRUE, showWarnings = FALSE)

fetch_page <- function(code = "") {
  Sys.sleep(10)
  url <- paste0(endpoint, "/?code=", code, "&showdescription=no")
  path <- file.path(bronze_dir, paste0(if (code == "") "root" else code, ".html"))
  download.file(url, path, method = "libcurl", mode = "wb", quiet = TRUE)
  read_html(path)
}

extract_codes <- function(page) {
  links <- html_elements(page, "a[href*=code]")
  hrefs <- html_attr(links, "href")
  names <- html_text2(links)
  keep <- !is.na(hrefs) & !is.na(names) & names != "Show text from Guidelines"
  hrefs <- hrefs[keep]
  names <- names[keep]
  codes <- sub(".*[?&]code=([^&]+).*", "\\1", hrefs)
  data.frame(atc_name = names, atc_code = codes, level = nchar(codes),
             stringsAsFactors = FALSE)
}

message("Fetching ATC root page")
page <- fetch_page()
combined <- extract_codes(page)

# The original crawler visits levels 1, 3, 4 and 5. Level 2 is not a
# separate ATC hierarchy level in the source's code format.
for (current_level in c(1L, 3L, 4L, 5L)) {
  message("Fetching level ", current_level)
  codes <- unique(combined$atc_code[combined$level == current_level])

  for (code in codes) {
    page <- fetch_page(code)
    combined <- rbind(combined, extract_codes(page))
    message("Code level ", code)
  }
  combined <- unique(combined)
}

message("Saved ", length(list.files(bronze_dir, pattern = "\\.html$")),
        " raw HTML pages to ", bronze_dir)
